    }

    #[test]
    fn clis_ok_on_plain_class_file() {
        let diags = lint_file(&*engine(), "classdef Foo\nend\n");
        assert!(!has_id(&diags, "CLIS"), "got: {diags:?}");
    }

    // -- CLTWO: multiple class definitions ----------------------------------

    #[test]
    fn cltwo_fires_on_two_classes() {
