    let ctx = file_ctx(&tree, source);
    rule.check_file(&ctx)
}

/// Returns true if any diagnostic has the given rule ID.
pub fn has_id(diags: &[Diagnostic], id: &str) -> bool {
    diags.iter().any(|d| d.rule_id == id)
}

