fn last_content_descendant(node: Node, source: &str) -> Node {
    let mut current = node;
    loop {
        let child_count = current.child_count();
        if child_count == 0 {
            return current;
        }
        // find last child that has non-whitespace text, else last child
        let last_child = (0..child_count).rev().find_map(|i| {
            let c = current.child(i)?;
            let t = &source[c.start_byte()..c.end_byte()];
            (!t.trim().is_empty()).then_some(c)
        }).or_else(|| current.child(child_count - 1));
        match last_child {
            Some(c) => current = c,
            None => return current,
        }
    }
}
```

