/// Classify a missing-END error node into a specific ENDCT variant.
fn classify_missing_end(node: &Node, source: &str) -> Option<(&'static str, String)> {
    let start = node.start_byte();
    let end = node.end_byte().min(source.len());
    let text = &source[start..end];
    let lower = text.to_lowercase();
    let line = node.start_position().row + 1;

    // ENDCT4: ERROR contains "classdef" followed by a function_definition
    // sibling with no "methods" in between.
    if lower.contains("classdef") {
        let mut sibling = node.next_sibling();
        while let Some(sib) = sibling {
            if sib.kind() == "function_definition" && sib.start_byte() > node.start_byte() {
                let between = &source[node.end_byte()..sib.start_byte()];
                if !between.to_lowercase().contains("methods") {
                    return Some((
                        "ENDCT4",
                        "A METHODS block or END might be missing before the function definition. This might be causing additional error messages.".to_string(),
                    ));
                }
                break;
            }
            sibling = sib.next_sibling();
        }
    }

    // ENDCT2: a block opener appears in the ERROR text or its previous
    // sibling, and the ERROR does not contain `end`.
    let has_end = lower.contains("end");
    if !has_end {
        let opener_in_text = BLOCK_OPENERS.iter().any(|kw| lower.contains(kw));
        let opener_in_prev = node
            .prev_sibling()
            .map(|prev| {
                let prev_text = &source[prev.start_byte()..prev.end_byte()];
                BLOCK_OPENERS.iter().any(|kw| prev_text.to_lowercase().contains(kw))
            })
            .unwrap_or(false);
        if opener_in_text || opener_in_prev {
            let end_line = {
                let raw = node.end_position().row;
                if source[..node.end_byte()].ends_with('\n') { raw } else { raw + 1 }
            };
            return Some((
                "ENDCT2",
                format!("An END might be missing (after line {end_line}), possibly matching line {line}."),
            ));
        }
    }

    // ENDCT3: the ERROR is followed by a sibling that starts with a
    // block-opening keyword.
    if let Some(next) = node.next_sibling() {
        let next_text = &source[next.start_byte()..next.end_byte()];
        let next_leading = next_text.split_whitespace().next().unwrap_or("").to_lowercase();
        if BLOCK_OPENERS.contains(&next_leading.as_str()) {
            let kw = text.split_whitespace().next().unwrap_or("").to_uppercase();
            let matched = next_leading.to_uppercase();
            return Some((
                "ENDCT3",
                format!("An END might be missing (before {kw} on line {line}), possibly matching {matched}."),
            ));
        }
    }

    None
}
```

