+                .to_uppercase();
+            let matched = next_leading.to_uppercase();
+            return Some((
+                "ENDCT3",
+                format!(
+                    "An END might be missing (before {kw} on line {line}), possibly matching {matched}."
+                ),
+            ));
+        }
+    }
